  // Seed initial data
  await seedInitialData(db);

  // Set up Express server
  const app = express();
  app.use(cors());
  app.use(express.json());

  // Serve frontend in production
  if (process.env.NODE_ENV === 'production') {
    app.use(express.static(path.join(__dirname, 'frontend/dist')));
  }

