  min-width: 320px;
  min-height: 100vh;
}

h1 {
  font-size: 3.2em;
  line-height: 1.1;
}

#app {
  max-width: 1280px;
  margin: 0 auto;
  padding: 2rem;
  text-align: center;
}

.logo {
  height: 6em;
  padding: 1.5em;
  will-change: filter;
  transition: filter 300ms;
}
.logo:hover {
  filter: drop-shadow(0 0 2em #646cffaa);
}
.logo.vanilla:hover {
  filter: drop-shadow(0 0 2em #f7df1eaa);
}

.card {
  padding: 2em;
}

.read-the-docs {
  color: #888;
}

/* Kanban Board Styles */
.kanban-board {
  display: flex;
  gap: 20px;
  padding: 20px;
  width: 100%;
  overflow-x: auto;
}

.column {
  flex: 0 0 300px;
  background: #f0f0f0;
  border-radius: 8px;
  padding: 16px;
  color: #333;
}

